CREATE TABLE public.daily_settings (id integer PRIMARY KEY DEFAULT 1, is_open boolean NOT NULL DEFAULT true, signups_open boolean NOT NULL DEFAULT true, wheel_open boolean NOT NULL DEFAULT true, start_date date NOT NULL DEFAULT '2026-10-01', end_date date NOT NULL DEFAULT '2026-10-31', welcome_coins integer NOT NULL DEFAULT 100, spin_cost integer NOT NULL DEFAULT 5, wheel_segments jsonb NOT NULL DEFAULT '[{"label":"+10","value":10,"weight":18},{"label":"💨","value":0,"weight":28},{"label":"+15","value":15,"weight":10},{"label":"💨","value":0,"weight":28},{"label":"+20","value":20,"weight":5},{"label":"🔁","value":-1,"weight":11}]'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.daily_settings TO anon, authenticated; GRANT ALL ON public.daily_settings TO service_role;
ALTER TABLE public.daily_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY daily_settings_public_read ON public.daily_settings FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.daily_players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, password_hash text NOT NULL, coins integer NOT NULL DEFAULT 0, blocked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.daily_players TO anon, authenticated; GRANT ALL ON public.daily_players TO service_role;
ALTER TABLE public.daily_players ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX daily_players_name_ci ON public.daily_players (lower(name));
CREATE POLICY daily_players_public_rank ON public.daily_players FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.daily_sessions (token_hash text PRIMARY KEY, player_id uuid NOT NULL REFERENCES public.daily_players(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
GRANT ALL ON public.daily_sessions TO service_role;
ALTER TABLE public.daily_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.daily_checkins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES public.daily_players(id) ON DELETE CASCADE, day date NOT NULL, coins integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(player_id,day));
GRANT SELECT ON public.daily_checkins TO anon, authenticated; GRANT ALL ON public.daily_checkins TO service_role;
ALTER TABLE public.daily_checkins ENABLE ROW LEVEL SECURITY;
CREATE POLICY daily_checkins_public_read ON public.daily_checkins FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.daily_spins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES public.daily_players(id) ON DELETE CASCADE, value integer NOT NULL, cost integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.daily_spins TO service_role;
ALTER TABLE public.daily_spins ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.daily_admin_roles (user_id uuid PRIMARY KEY, role text NOT NULL DEFAULT 'admin' CHECK (role = 'admin'));
GRANT SELECT ON public.daily_admin_roles TO authenticated; GRANT ALL ON public.daily_admin_roles TO service_role;
ALTER TABLE public.daily_admin_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY daily_admin_roles_self ON public.daily_admin_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.daily_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.daily_admin_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.daily_is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_is_admin() TO authenticated;
CREATE OR REPLACE FUNCTION public.daily_player_view(p public.daily_players) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $$ SELECT jsonb_build_object('id',p.id,'name',p.name,'coins',p.coins,'blocked',p.blocked,'created_at',p.created_at) $$;
REVOKE ALL ON FUNCTION public.daily_player_view(public.daily_players) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.daily_access(p_name text, p_password text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.daily_players; s public.daily_settings; token text; BEGIN IF length(trim(coalesce(p_name,''))) < 3 OR length(trim(p_name)) > 20 THEN RAISE EXCEPTION 'invalid_name'; END IF; IF length(coalesce(p_password,'')) < 4 OR length(p_password) > 72 THEN RAISE EXCEPTION 'invalid_password'; END IF; SELECT * INTO s FROM public.daily_settings WHERE id=1; SELECT * INTO p FROM public.daily_players WHERE lower(name)=lower(trim(p_name)); IF NOT FOUND THEN IF NOT s.signups_open THEN RAISE EXCEPTION 'signups_closed'; END IF; INSERT INTO public.daily_players(name,password_hash,coins) VALUES (trim(p_name),crypt(p_password,gen_salt('bf')),s.welcome_coins) RETURNING * INTO p; ELSE IF p.password_hash <> crypt(p_password,p.password_hash) THEN RAISE EXCEPTION 'wrong_password'; END IF; END IF; IF p.blocked THEN RAISE EXCEPTION 'blocked'; END IF; token := encode(gen_random_bytes(32),'hex'); INSERT INTO public.daily_sessions(token_hash,player_id,expires_at) VALUES (encode(digest(token,'sha256'),'hex'),p.id,now()+interval '30 days'); RETURN jsonb_build_object('token',token,'player',public.daily_player_view(p)); END $$;
REVOKE ALL ON FUNCTION public.daily_access(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_access(text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.daily_current(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.daily_players; BEGIN SELECT u.* INTO p FROM public.daily_players u JOIN public.daily_sessions s ON s.player_id=u.id WHERE s.token_hash=encode(digest(coalesce(p_token,''),'sha256'),'hex') AND s.expires_at > now(); IF NOT FOUND OR p.blocked THEN RAISE EXCEPTION 'session_expired'; END IF; RETURN public.daily_player_view(p); END $$;
REVOKE ALL ON FUNCTION public.daily_current(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_current(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.daily_claim(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.daily_players; s public.daily_settings; d date := (now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN SELECT u.* INTO p FROM public.daily_players u JOIN public.daily_sessions x ON x.player_id=u.id WHERE x.token_hash=encode(digest(coalesce(p_token,''),'sha256'),'hex') AND x.expires_at > now() FOR UPDATE OF u; IF NOT FOUND OR p.blocked THEN RAISE EXCEPTION 'session_expired'; END IF; SELECT * INTO s FROM public.daily_settings WHERE id=1; IF NOT s.is_open OR d<s.start_date OR d>s.end_date THEN RAISE EXCEPTION 'game_closed'; END IF; IF EXISTS (SELECT 1 FROM public.daily_checkins WHERE player_id=p.id AND day=d) THEN RAISE EXCEPTION 'already_claimed'; END IF; INSERT INTO public.daily_checkins(player_id,day,coins) VALUES(p.id,d,extract(day from d)::integer); UPDATE public.daily_players SET coins=coins+extract(day from d)::integer WHERE id=p.id RETURNING * INTO p; RETURN jsonb_build_object('reward',extract(day from d)::integer,'player',public.daily_player_view(p)); END $$;
REVOKE ALL ON FUNCTION public.daily_claim(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_claim(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.daily_spin(p_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.daily_players; s public.daily_settings; seg jsonb; chosen jsonb; total numeric := 0; roll numeric; cumulative numeric := 0; v integer; c integer; d date := (now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN SELECT u.* INTO p FROM public.daily_players u JOIN public.daily_sessions x ON x.player_id=u.id WHERE x.token_hash=encode(digest(coalesce(p_token,''),'sha256'),'hex') AND x.expires_at > now() FOR UPDATE OF u; IF NOT FOUND OR p.blocked THEN RAISE EXCEPTION 'session_expired'; END IF; SELECT * INTO s FROM public.daily_settings WHERE id=1; IF NOT s.is_open OR NOT s.wheel_open OR d<s.start_date OR d>s.end_date THEN RAISE EXCEPTION 'game_closed'; END IF; c:=s.spin_cost; IF c<0 OR p.coins<c THEN RAISE EXCEPTION 'insufficient_coins'; END IF; SELECT sum(greatest(0,(x->>'weight')::numeric)) INTO total FROM jsonb_array_elements(s.wheel_segments) x; IF total IS NULL OR total<=0 THEN RAISE EXCEPTION 'invalid_wheel'; END IF; roll:=random()*total; FOR seg IN SELECT value FROM jsonb_array_elements(s.wheel_segments) LOOP cumulative:=cumulative+greatest(0,(seg->>'weight')::numeric); IF roll<cumulative THEN chosen:=seg; EXIT; END IF; END LOOP; v:=(chosen->>'value')::integer; UPDATE public.daily_players SET coins=coins-c+CASE WHEN v=-1 THEN c ELSE v END WHERE id=p.id RETURNING * INTO p; INSERT INTO public.daily_spins(player_id,value,cost) VALUES(p.id,v,c); RETURN jsonb_build_object('value',v,'player',public.daily_player_view(p)); END $$;
REVOKE ALL ON FUNCTION public.daily_spin(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_spin(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.daily_admin(p_action text,p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE s public.daily_settings; segments jsonb; elem jsonb; BEGIN IF NOT public.daily_is_admin() THEN RAISE EXCEPTION 'not_authorized'; END IF; IF p_action='settings' THEN segments:=p_payload->'wheel_segments'; IF segments IS NOT NULL THEN IF jsonb_typeof(segments)<>'array' OR jsonb_array_length(segments)<>6 THEN RAISE EXCEPTION 'invalid_wheel'; END IF; FOR elem IN SELECT value FROM jsonb_array_elements(segments) LOOP IF (elem->>'weight')::numeric<0 OR (elem->>'weight')::numeric>100 OR (elem->>'value')::integer < -1 OR (elem->>'value')::integer>10000 OR length(elem->>'label')>20 THEN RAISE EXCEPTION 'invalid_wheel'; END IF; END LOOP; END IF; UPDATE public.daily_settings SET is_open=coalesce((p_payload->>'is_open')::boolean,is_open),signups_open=coalesce((p_payload->>'signups_open')::boolean,signups_open),wheel_open=coalesce((p_payload->>'wheel_open')::boolean,wheel_open),welcome_coins=greatest(0,least(10000,coalesce((p_payload->>'welcome_coins')::integer,welcome_coins))),spin_cost=greatest(0,least(10000,coalesce((p_payload->>'spin_cost')::integer,spin_cost))),wheel_segments=coalesce(segments,wheel_segments),updated_at=now() WHERE id=1 RETURNING * INTO s; RETURN to_jsonb(s); ELSIF p_action='adjust' THEN UPDATE public.daily_players SET coins=greatest(0,coalesce((p_payload->>'coins')::integer,coins)),blocked=coalesce((p_payload->>'blocked')::boolean,blocked) WHERE id=(p_payload->>'id')::uuid; ELSIF p_action='remove' THEN DELETE FROM public.daily_players WHERE id=(p_payload->>'id')::uuid; ELSIF p_action='reset' THEN IF (p_payload->>'confirm') <> 'RESETAR' THEN RAISE EXCEPTION 'confirmation_required'; END IF; DELETE FROM public.daily_spins; DELETE FROM public.daily_checkins; DELETE FROM public.daily_sessions; UPDATE public.daily_players SET coins=0; ELSE RAISE EXCEPTION 'invalid_action'; END IF; RETURN jsonb_build_object('ok',true); END $$;
REVOKE ALL ON FUNCTION public.daily_admin(text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_admin(text,jsonb) TO authenticated;